SALT = b'sha256'
SHA = hashlib.sha256


def win(value):
    print('flag{' + value + '}')
    raise SystemExit


def check_sha(value):
    data = value.encode('utf-8')
    if SHA(data + SALT).digest() == TARGET or SHA(SALT + data).digest() == TARGET:
