def hmac_sha256(key, message):
    if len(key) > 64:
        key = SHA(key).digest()
    key += bytes(64 - len(key))
    outer = bytes(x ^ 92 for x in key)
    inner = bytes(x ^ 54 for x in key)
    return SHA(outer + SHA(inner + message).digest()).digest()


def check_extended(value):
    data = value.encode('utf-8')
    salts = (b'sha256', b'SHA256', b'sha-256', b'SHA-256', b'sha_256')
    separators = (b'', b':', b'$', b'_', bytes((0,)))
    if SHA(data).digest() == TARGET:
        win(value)
    for salt in salts:
        for separator in separators:
            if SHA(data + separator + salt).digest() == TARGET:
                win(value)
            if SHA(salt + separator + data).digest() == TARGET:
                win(value)
