    padding = rate - len(data) % rate
    if padding == 1:
        message = data + bytes((129,))
    else:
        message = data + bytes((1,)) + bytes(padding - 2) + bytes((128,))
    state = [0] * 25
    for offset in range(0, len(message), rate):
        block = message[offset:offset + rate]
